"""bot/embedded.py is generated by tools/embed_data.py; it must match its sources."""
import json
from pathlib import Path

import numpy as np

from tools import embed_data

ROOT = Path(__file__).resolve().parent.parent
FIX = "python -m tools.embed_data"


def test_committed_embedded_file_is_current() -> None:
    bad = embed_data.problems()
    assert not bad, f"bot/embedded.py is stale ({'; '.join(bad)}). Run:  .venv/bin/{FIX}"


def test_embedded_file_is_under_the_size_cap() -> None:
    assert (ROOT / "bot" / "embedded.py").stat().st_size <= embed_data.MAX_BYTES


def test_embedded_names_load_without_numpy() -> None:
    ns: dict = {}
    exec(compile((ROOT / "bot" / "embedded.py").read_text(), "embedded", "exec"), ns)
    assert ns["SPEC"]["name"] and set(ns["PARAMS"]) >= {"tier1", "tier2"}
    assert not any(k.startswith("_") for p in ns["PARAMS"].values() for k in p)


def _fake_tables(root: Path, spec, n: int = 3) -> None:
    """A minimal valid data/<name>/ for `spec`: classes + eq_random + meta."""
    d = root / spec.name
    d.mkdir(parents=True)
    np.save(d / "classes.npy", np.arange(n, dtype=np.int16))
    np.save(d / "eq_random.npy", np.linspace(0.3, 0.7, n))
    (d / "meta.json").write_text(json.dumps({
        "spec_hash": embed_data.spec_hash(spec), "n_classes": n, "hole_size": 2,
        "complete": {"equity_random": True}}))


def test_tables_are_embedded_when_they_match(tmp_path) -> None:
    spec, _ = embed_data.load_spec("holdem_nl")
    _fake_tables(tmp_path, spec)
    text = embed_data.render("holdem_nl", data_dir=tmp_path)
    ns: dict = {}
    exec(compile(text, "embedded", "exec"), ns)
    from bot.artifacts import decode_npy
    files = ns["ARTIFACTS"]["tables"]["files"]
    assert decode_npy(files["eq_random"]).shape == (3,) and set(files) == {"classes", "eq_random"}
    assert not embed_data.problems(_write(tmp_path, text), "holdem_nl", data_dir=tmp_path)


def test_stale_tables_are_not_embedded(tmp_path) -> None:
    spec, _ = embed_data.load_spec("holdem_nl")
    _fake_tables(tmp_path, spec)
    meta = tmp_path / spec.name / "meta.json"
    meta.write_text(json.dumps({**json.loads(meta.read_text()), "spec_hash": "0" * 16}))
    assert "ARTIFACTS = {}" in embed_data.render("holdem_nl", data_dir=tmp_path)


def test_stale_file_is_reported(tmp_path) -> None:
    text = embed_data.render("holdem_nl")
    stale = _write(tmp_path, text.replace("'big_blind': 2", "'big_blind': 3"))
    assert any("SPEC" in p for p in embed_data.problems(stale, "holdem_nl"))


def test_size_cap_is_enforced(tmp_path, monkeypatch) -> None:
    import pytest
    monkeypatch.setattr(embed_data, "MAX_BYTES", 100)
    with pytest.raises(SystemExit, match="cap"):
        embed_data.render("holdem_nl")


def _write(tmp_path: Path, text: str) -> Path:
    p = tmp_path / "embedded.py"
    p.write_text(text)
    return p
